2	 * live-tools-check.test.ts — where the live tool check is wired, and the one place
3	 * it must never be.
4	 *
5	 * ## The two halves, and why they are pinned together
6	 *
7	 * `atoma validate --with-live-tools` starts the servers a definition names. That
8	 * makes it the one check in this system that EXECUTES configuration, and it
9	 * therefore cannot run where a pull request's configuration is the input:
10	 * `validate_deliverable.ts` reads `.github/atomaton/` as data and runs nothing under
11	 * `--root`, and `tools.servers` lets anyone write an arbitrary `command`. Wiring it
12	 * there would turn "a check that runs nothing" into "a check that runs the pull
13	 * request", inside the job that decides whether that pull request may merge.
14	 *
15	 * So it is wired at the other end: `.github/atomaton/scripts/publish-release.sh`, which runs from a
16	 * release tag, against `dist/` — the artifact about to be published. These tests hold both
17	 * ends, because either one alone is half a rule: the check existing is useless if
18	 * nothing calls it, and the check being called is dangerous if it is called from
19	 * the pull request path.
20	 *
21	 * ## Why ordering is asserted rather than described
22	 *
23	 * `publish-release.sh` builds the artifact with `bun run synth` and publishes it with
24	 * `gh release create`. The check has to sit between them: before the build there
25	 * is no `dist/` to check (it is gitignored, so a fresh checkout has none), and
26	 * after the publish a failure would arrive too late to withhold anything. Both
27	 * directions are silent — a check that ran first would fail on a missing
28	 * directory, and one that ran last would leave the release standing — so the order
29	 * is pinned here rather than left to whoever next edits the script.
30	 */
31	import { describe, expect, test } from "bun:test";
32	import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
33	import { resolveDeployJobs } from "../../src/domain/delivery/deploy-jobs.ts";
34	
35	const CHECK = ".github/atomaton/scripts/check-live-tools.sh";
36	const RELEASE = ".github/atomaton/scripts/publish-release.sh";
37	const DELIVERABLE_VALIDATOR = "src/entrypoints/machinery/validate_deliverable.ts";
38	
39	function body(path: string): string {
40	  return readFileSync(path, "utf8").replaceAll("\r\n", "\n");
41	}
42	
43	describe("the live tool check", () => {
44	  test("exists, and is a shell script this repository owns", () => {
45	    expect(existsSync(CHECK), `${CHECK} is missing; nothing calls --with-live-tools`).toBe(true);
46	    expect(body(CHECK).startsWith("#!/usr/bin/env bash")).toBe(true);
47	    // Executable, because the deploy runs it as a program. It is invoked through
48	    // `bash` below as well, so losing the bit is not fatal -- but a file that is
49	    // only ever invoked explicitly is one nobody notices has stopped being runnable.
50	    if (process.platform !== "win32") {
51	      expect(statSync(CHECK).mode & 0o111, `${CHECK} is not executable`).not.toBe(0);
52	    }
53	  });
54	
55	  test("it asks atoma the question that needs live servers", () => {
56	    const source = body(CHECK);
57	    // Both flags: `--with-live-tools` without a tools file is refused by atoma, and
58	    // a script that lost either one would report a clean pass having asked nothing.
59	    expect(source, "the check must ask the live question").toContain("--with-live-tools");
60	    expect(source, "the live question needs the tools file").toContain("--tools-file");
61	  });
62	
63	  /**
64	   * The binary it checks with is the one a run installs.
65	   *
66	   * `--with-live-tools` only exists from atoma v0.1.37, and the checks are the
67	   * BINARY's rather than this repository's — so a check run against an older or
68	   * other binary answers a different question while looking identical. The pin is
69	   * read from `actions/atoma-cli.ts` rather than repeated, so raising it cannot
70	   * leave this quietly checking something else.
71	   */
72	  test("the version is read from the pin, not written a second time", () => {
73	    const source = body(CHECK);
74	    expect(source, "the pin is the single declaration of which binary runs").toContain("ATOMA_DEFAULT_VERSION");
75	    expect(source).toContain("src/workflows/actions/atoma-cli.ts");
76	    // The download URL is built from what was read, so there is no tag literal to
77	    // drift away from the pin.
78	    expect(source).toContain("releases/download/${VERSION}/atoma-linux-x86_64");
79	    // And a fetch that fails must fail the check. `curl` without `-f` writes the
80	    // error page to the file and exits 0, which is the shape this guards against:
81	    // the binary would then be un-runnable and the script would carry on.
82	    expect(source, "curl must fail the step on an HTTP error").toContain("curl -fsSL");
83	  });
84	
85	  /**
86	   * `dist/` and never `.github/`.
87	   *
88	   * `.github/` in this repository is the last RELEASE, put there by the self-deploy
89	   * workflow, so it is a copy of something that already passed this check. `dist/`
90	   * is built from the default branch by the step above and is what an adopter
91	   * receives — which is the only tree whose consistency is worth asking about.
92	   */
