103	   * Every definition, not a chosen one.
104	   *
105	   * A server only the orchestrator names is still a server this release hands an
106	   * adopter, and a `for` over the directory is what makes a fourth definition
107	   * covered without anyone remembering to add it here.
108	   */
109	  test("it validates every definition the artifact ships", () => {
110	    const source = body(CHECK);
111	    expect(source, "a hard-coded definition name would skip the rest").toContain('for def in "$DEFS_DIR"/*.md');
112	  });
113	});
